type Config struct { Name string; Ports []int }   // treat as read-only once stored
var current atomic.Pointer[Config]

func Load() *Config { return current.Load() }     // readers get a stable snapshot

func (c *Config) WithName(name string) *Config {
	return &Config{Name: name, Ports: c.Ports}     // new version; shares Ports
}

func SetName(name string) { current.Store(current.Load().WithName(name)) }
